INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (8, 1, 'theory', 'Quiz: the file system, inodes and links');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 1, 0, 'Where is a file''s name stored in Linux?', '["In the inode, next to permissions and size", "In a directory entry: a \"name, inode number\" pair", "In the first data block of the file itself", "In the file system''s superblock"]', 1, 'An inode describes a file without a name. The name lives in the directory, so renaming edits one row of the table and doesn''t touch the data.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 1, 1, 'You deleted a huge log with rm, but a process still has it open. What happens to the disk space?', '["It is freed right after rm", "It is freed only after a reboot", "The system won''t let you delete an open file", "It isn''t freed until the process closes the file: the inode lives as long as an open descriptor exists"]', 3, 'rm removes the name, but the inode is freed only when both the names and the open descriptors are gone. The cure is to restart the program or close the descriptor.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 1, 2, 'What happens to the links after the "original" file name is deleted?', '["Both keep working", "Both become dangling", "The hard link keeps working, and the symbolic link becomes dangling", "The hard link becomes dangling, and the symbolic link keeps working"]', 2, 'A hard link is another name for the same inode, and the data lives until the name count reaches zero. A symbolic link stores only a path, and without its target it points into the void.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 1, 3, 'The df -h command shows free gigabytes, but you can''t create a file: "no space left on device". What should you check?', '["Free inodes with df -i: millions of small files could have exhausted them", "The size of the file system journal", "The TMPDIR environment variable", "Permissions on the root directory"]', 0, 'The number of inodes is set when the file system is created. Small files can exhaust the inodes before the space, and the kernel answers with the same error.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 1, 4, 'How does journaling (ext4, XFS) differ from copy-on-write (Btrfs)?', '["A journal stores copies of files, and CoW stores only names", "CoW works only in main memory", "There is no difference: they are two names for one mechanism", "A journal records the intent and modifies data in place, while CoW writes a new copy and switches a pointer"]', 3, 'After a crash the journal is replayed or rolled back; with CoW the old version stays intact, which makes snapshots cheap.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 1, 5, 'What does the command mount /dev/sdb1 /mnt do?', '["Copies all the disk''s files into the /mnt directory", "Attaches the device''s file system to the /mnt directory: a path through this point now leads into it", "Formats the partition and creates a /mnt directory in it", "Creates a symbolic link to the device inside /mnt"]', 1, 'Mounting doesn''t copy data. The kernel remembers the mount point and, during path lookup, moves into the root of the attached file system.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 1, 6, 'What is the /proc directory?', '["A window into the kernel: its files are created on the fly and show processes and system state; they aren''t on disk", "A directory on disk where processes'' temporary files live", "A swap partition that is visible as a directory", "An archive of the logs of all running programs"]', 0, 'It is a virtual file system. Reading a file calls a kernel function that produces the needed text right now.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 1, 7, 'Why can''t you make a hard link to a file on another file system?', '["Another file system always has different access permissions", "The kernel can''t read other directories", "A directory entry stores an inode number, which is unique only within its own file system", "Hard links are allowed only in the home directory"]', 2, 'A hard link is another name for the same inode. Across a file system boundary the number means nothing, so a symbolic link with a path is needed there.');
